import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"53、【漸】 艮下巽上","description":"橫渠易說 - 53、【漸】 艮下巽上","frontmatter":{"title":"53、【漸】 艮下巽上","description":"橫渠易說 - 53、【漸】 艮下巽上"},"headers":[],"relativePath":"classics/hengqu/055.md","filePath":"classics/hengqu/055.md"}'),l={name:"classics/hengqu/055.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_53、【漸】-艮下巽上" tabindex="-1">53、【漸】 艮下巽上 <a class="header-anchor" href="#_53、【漸】-艮下巽上" aria-label="Permalink to “53、【漸】 艮下巽上”">​</a></h1><h3 id="彖曰-漸之進也-女歸吉也。進得位-往有功也-進以正-可以正邦也。其位-剛得中也-止而巽-動不窮也。" tabindex="-1">彖曰：漸之進也，女歸吉也。進得位，往有功也；進以正，可以正邦也。其位，剛得中也；止而巽，動不窮也。 <a class="header-anchor" href="#彖曰-漸之進也-女歸吉也。進得位-往有功也-進以正-可以正邦也。其位-剛得中也-止而巽-動不窮也。" aria-label="Permalink to “彖曰：漸之進也，女歸吉也。進得位，往有功也；進以正，可以正邦也。其位，剛得中也；止而巽，動不窮也。”">​</a></h3><p>漸者，天地之施交。“女歸吉”，“進得位”，皆指六四。施一作始。</p><h3 id="象曰-山上有木-漸-君子以居賢德善俗。" tabindex="-1">象曰：山上有木，漸，君子以居賢德善俗。 <a class="header-anchor" href="#象曰-山上有木-漸-君子以居賢德善俗。" aria-label="Permalink to “象曰：山上有木，漸，君子以居賢德善俗。”">​</a></h3><p>居可久之德，難從無徵之德，君子不以責人。君子以賢德自居，不強率人，待其心回，故善俗自然。一作不可推行無徵難從之德。</p><h3 id="初六-鴻漸於乾-小子厲-有言無咎。-象曰-小子之厲-義無咎也。" tabindex="-1">初六，鴻漸於乾，小子厲，有言無咎。 象曰：小子之厲，義無咎也。 <a class="header-anchor" href="#初六-鴻漸於乾-小子厲-有言無咎。-象曰-小子之厲-義無咎也。" aria-label="Permalink to “初六，鴻漸於乾，小子厲，有言無咎。 象曰：小子之厲，義無咎也。”">​</a></h3><p>鴻為水鳥，漸進之始，出至於乾。鴻鵠之志非小子所量，見其出陸，爭欲危之，且疑其所處，非君子信己而行，義無咎也。</p><h3 id="六二-鴻漸於磐-飲食衎衎-吉。-象曰-飲食衎衎-不素飽也。" tabindex="-1">六二，鴻漸於磐，飲食衎衎，吉。 象曰：“飲食衎衎”，不素飽也。 <a class="header-anchor" href="#六二-鴻漸於磐-飲食衎衎-吉。-象曰-飲食衎衎-不素飽也。" aria-label="Permalink to “六二，鴻漸於磐，飲食衎衎，吉。 象曰：“飲食衎衎”，不素飽也。”">​</a></h3><p>衎衎，和樂貌。飲食和樂，不徒飽而已，言獲志之多也。</p><h3 id="九三-鴻漸於陸-夫徵不復-婦孕不育-兇-利禦寇。-象曰-夫徵不復-離群醜也-婦孕不育-失其道也-利用禦寇-順相保也。" tabindex="-1">九三，鴻漸於陸，夫徵不復，婦孕不育，兇，利禦寇。 象曰：“夫徵不復”，離群醜也；“婦孕不育”，失其道也；“利用禦寇”，順相保也。 <a class="header-anchor" href="#九三-鴻漸於陸-夫徵不復-婦孕不育-兇-利禦寇。-象曰-夫徵不復-離群醜也-婦孕不育-失其道也-利用禦寇-順相保也。" aria-label="Permalink to “九三，鴻漸於陸，夫徵不復，婦孕不育，兇，利禦寇。 象曰：“夫徵不復”，離群醜也；“婦孕不育”，失其道也；“利用禦寇”，順相保也。”">​</a></h3><p>漸卦九三、六四易位而居，三離上卦，四離下體，故曰“夫徵不復，婦孕不育”，然相與之固，物莫能間，故利用禦寇也。“徵不復”者，變為艮且得位也，如六四之得桷；三四非正合，故曰“失其道”也。</p><h3 id="六四-鴻漸於木-或得其桷-無咎。-象曰-或得其桷-順以巽也。" tabindex="-1">六四，鴻漸於木，或得其桷，無咎。 象曰：“或得其桷”，順以巽也。 <a class="header-anchor" href="#六四-鴻漸於木-或得其桷-無咎。-象曰-或得其桷-順以巽也。" aria-label="Permalink to “六四，鴻漸於木，或得其桷，無咎。 象曰：“或得其桷”，順以巽也。”">​</a></h3><p>木非鴻所居，如四之易位而在上也，然本坤之爻，進而為巽，故或得其桷，居之可安也。順巽則眾所與也，故得所安。</p><h3 id="九五-鴻漸於陵-婦三歲不孕-終莫之勝-吉。-象曰-終莫之勝吉-得所願也。" tabindex="-1">九五，鴻漸於陵，婦三歲不孕，終莫之勝，吉。 象曰：“終莫之勝吉”，得所願也。 <a class="header-anchor" href="#九五-鴻漸於陵-婦三歲不孕-終莫之勝-吉。-象曰-終莫之勝吉-得所願也。" aria-label="Permalink to “九五，鴻漸於陵，婦三歲不孕，終莫之勝，吉。 象曰：“終莫之勝吉”，得所願也。”">​</a></h3><h3 id="上九-鴻漸於陸-其羽可用為儀-吉。-象曰-其羽可用為儀吉-不可亂也。" tabindex="-1">上九，鴻漸於陸，其羽可用為儀，吉。 象曰：“其羽可用為儀吉”，不可亂也。 <a class="header-anchor" href="#上九-鴻漸於陸-其羽可用為儀-吉。-象曰-其羽可用為儀吉-不可亂也。" aria-label="Permalink to “上九，鴻漸於陸，其羽可用為儀，吉。 象曰：“其羽可用為儀吉”，不可亂也。”">​</a></h3><p>無應於下，羽潔無汙，且處於高，故曰漸陸。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
